const designs = {
 garden: {name:'Little world', ko:'초록 학습실', note:'그림책의 여백, 둥근 책장, 초록빛 교실', tagline:'오늘은 어떤 이야기를\n배워 볼까요?', en:'A little English,\na bigger world.'},
 press: {name:'Momo press', ko:'나의 영어 잡지', note:'큰 활자, 선명한 파랑, 비대칭 편집', tagline:'오늘의 영어를\n펼쳐 봐요.', en:'Small words.\nBig stories.'},
 studio: {name:'Momo studio', ko:'나만의 영어 스튜디오', note:'차분한 어둠, 앨범형 수업, 소리에 집중', tagline:'내 목소리로\n시작하는 영어.', en:'Find your voice.'},
 planner: {name:'Daily momo', ko:'매일의 학습 플래너', note:'흰 종이, 단정한 목록, 명확한 다음 행동', tagline:'하나씩, 내 속도로\n배워요.', en:'Make room\nfor English.'}
};
const key = new URLSearchParams(location.search).get('design') || 'garden';
const d = designs[key] || designs.garden;
document.body.className = designs[key] ? key : 'garden';
document.title = `${d.ko} · 모모 디자인 목업`;
const subjects = [
 {id:'read',name:'읽기',en:'Read',level:3,topic:'동물 친구들',title:'A little cat',desc:'짧은 이야기를 읽고 뜻을 찾아요.',done:true},
 {id:'write',name:'쓰기',en:'Write',level:2,topic:'내가 좋아하는 것',title:'I like apples',desc:'단어를 골라 문장을 만들어요.',done:false},
 {id:'speak',name:'말하기',en:'Speak',level:2,topic:'나를 소개해요',title:'Hello, this is me',desc:'듣고, 내 목소리로 말해 봐요.',done:false},
 {id:'talk',name:'회화',en:'Talk',level:1,topic:'이름과 나이',title:'Meet Mina',desc:'미나 선생님과 인사해요.',done:false}
];
const portrait='../teacher-avatar/public/portraits/mina.png';
const leaf=`<svg viewBox="0 0 400 320" fill="none" aria-hidden="true"><path d="M196 273V111" stroke="#254d3e" stroke-width="7"/><path d="M199 189C123 195 72 159 71 102C140 98 185 124 199 189Z" fill="#769a6c"/><path d="M201 139C195 69 238 29 301 37C300 97 258 136 201 139Z" fill="#254d3e"/><path d="M201 237C211 175 252 154 320 169C301 226 255 248 201 237Z" fill="#adc0a2"/><path d="M138 252H257L244 306H152L138 252Z" fill="#c6a77a"/><path d="M32 287H120V306H32Z" fill="#c4d9e1"/><path d="M41 268H115V286H41Z" fill="#254d3e"/><text x="48" y="282" font-size="13" fill="white" font-family="Georgia">little words</text><circle cx="340" cy="72" r="23" fill="#ead88c"/></svg>`;
const arrows='<span aria-hidden="true">↗</span>';
function subject(s){return `<button class="subject ${s.id}" data-subject="${s.id}"><span class="subject-top"><span>${s.name}</span><span class="level">${s.level}단계</span></span><span class="subject-en" aria-hidden="true">${s.en}<span>↗</span></span><span class="topic">${s.topic}</span><span class="subject-end">${s.done?'오늘 한 수업 있어요':'수업 고르기'} <span aria-hidden="true">→</span></span></button>`}
const nav=`<nav aria-label="주 메뉴"><a href="?design=${key}" aria-current="page">오늘의 학습</a><button data-review>단어 복습</button><button data-parent>부모님</button></nav>`;
const brand=`<a class="brand" href="index.html" aria-label="모모 디자인 비교로 돌아가기">momo<span>english academy</span></a>`;
const teacher=`<section class="teacher"><div class="teacher-portrait"><img src="${portrait}" alt="미나 선생님" width="300" height="300"></div><div class="teacher-copy"><h2>미나와 이야기해요</h2><p>틀려도 괜찮아.<br>함께 천천히 말해 보자!</p><button class="text-button" data-subject="talk">회화 수업 고르기 ${arrows}</button></div></section>`;
const review=`<section class="review"><div><h2>다시 만나면 오래 기억해요</h2><p>복습할 단어 <strong>14개</strong></p></div><button data-review>단어 복습하기 <span aria-hidden="true">→</span></button></section>`;
const title=`<div class="greeting"><div><h1>${d.tagline.replace('\n','<br>')}</h1><p>원하는 영역부터 골라요.</p></div><span class="profile">모모의 학습실</span></div>`;
const allSubjects=subjects.map(subject).join('');
let content='';
if(key==='press') content=`<header>${brand}${nav}</header><main id="main"><div class="press-intro"><h1>${d.en.replace('\n','<br>')}</h1><div><p class="korean-title">오늘의 영어를 펼쳐 봐요.</p><p>읽고, 쓰고, 말하는<br>나만의 작은 영어 잡지.</p><span class="profile">모모의 학습실</span></div></div><div class="press-layout"><section class="subjects" aria-label="학습 영역">${allSubjects}</section>${teacher}</div>${review}</main>`;
else if(key==='studio') content=`<header>${brand}${nav}</header><main id="main">${title}<div class="studio-layout"><section class="studio-feature"><div class="record" aria-hidden="true"><div class="record-center">m<br>m</div></div><div class="feature-text"><p>오늘의 회화 · 이름과 나이</p><h2>Find your voice.</h2><p>미나 선생님과<br>첫 이야기를 시작해요.</p><button class="primary" data-subject="talk">회화 수업 고르기 ${arrows}</button></div><img class="studio-mina" src="${portrait}" alt="미나 선생님" width="240" height="240"></section><section class="subjects" aria-label="학습 영역">${allSubjects}</section></div>${review}</main>`;
else if(key==='planner') content=`<div class="planner-shell"><aside>${brand}${nav}<div class="aside-bottom">조금씩 배우는 영어,<br>차곡차곡 쌓이는 나.</div><a href="index.html" class="backboard">디자인 비교로 돌아가기</a></aside><main id="main"><header><span>모모의 학습 플래너</span><span class="profile">모모의 학습실</span></header>${title}<div class="planner-layout"><section class="lesson-list"><div class="list-heading"><h2>오늘의 학습</h2><span>${subjects.filter(x=>x.done).length}개 영역에서 공부했어요</span></div>${subjects.map(s=>`<button class="planner-row" data-subject="${s.id}"><span class="row-name">${s.name}<small>${s.en}</small></span><span class="row-topic">${s.topic}<small>${s.level}단계 · 수업 고르기</small></span><span class="row-status">${s.done?'오늘 학습함':'시작해요'} <span aria-hidden="true">→</span></span></button>`).join('')}</section><div class="planner-side">${teacher}<section class="week"><h2>이번 주 발자국</h2><div class="weekdays">${['월','화','수','목','금'].map((s,i)=>`<span>${s}<b class="${i<3?'visited':''}" aria-label="${i<3?'학습함':'아직 학습하지 않음'}">${i<3?'✓':'–'}</b></span>`).join('')}</div><p>이번 주에 3일 만났어요.</p></section></div></div>${review}</main></div>`;
else content=`<header>${brand}${nav}</header><main id="main">${title}<div class="garden-layout"><section class="garden-story"><div><h2>${d.en.replace('\n','<br>')}</h2><p>작은 단어 하나가<br>새로운 세상을 열어 줘요.</p></div>${leaf}<span class="story-footer">차근차근 자라는 나의 영어</span></section><section class="subjects" aria-label="학습 영역">${allSubjects}</section></div><div class="garden-bottom">${teacher}${review}</div></main>`;
document.querySelector('#app').innerHTML=`<a class="skip" href="#main">본문으로 건너뛰기</a><div class="mockup-note"><a href="index.html">← 네 가지 디자인 비교</a><span>${d.name} · 화면 목업 / 예시 데이터</span></div>${content}<dialog aria-labelledby="dialog-title"><div class="dialog-head"><span>모모 잉글리시</span><button class="close" aria-label="닫기">×</button></div><div id="dialog-content"></div></dialog>`;
const dialog=document.querySelector('dialog');
const panel=document.querySelector('#dialog-content');
let trigger;
function open(html){trigger=document.activeElement;panel.innerHTML=html;if(!dialog.open)dialog.showModal();panel.querySelector('h2')?.focus();}
function heading(text){return `<h2 id="dialog-title" tabindex="-1">${text}</h2>`}
function lesson(id){const s=subjects.find(x=>x.id===id);open(`${heading(`${s.name} 수업을 골라요`)}<p>${s.level}단계 · ${s.topic}</p><button class="lesson-choice" data-start="${s.id}"><span><b>${s.title}</b><small>${s.desc}</small></span><span aria-hidden="true">→</span></button><p class="demo-help">목업에서는 이 수업 한 개를 미리 볼 수 있어요.</p>`)}
function start(id){const s=subjects.find(x=>x.id===id);let inner='';if(id==='read')inner=`<article class="reading"><p>A little cat sits on a mat.<br>The cat likes the sun.</p></article><p>고양이는 무엇을 좋아하나요?</p><div class="answers"><button data-answer="correct">햇빛</button><button data-answer="try">비</button></div><p class="feedback" role="status"></p>`;if(id==='write')inner=`<p>“나는 사과를 좋아해.” 순서대로 골라요.</p><div class="sentence" aria-live="polite">단어를 골라요.</div><div class="answers">${['apples','I','like'].map(x=>`<button data-word="${x}">${x}</button>`).join('')}</div><button class="reset" data-reset>처음부터 고르기</button><p class="feedback" role="status"></p>`;if(id==='speak')inner=`<p class="english">Hello, my name is Momo.</p><p>듣고, 내 목소리로 인사해 봐요.</p><button class="primary" data-speech>문장 듣기</button><p class="feedback" role="status">목업에서는 마이크를 켜거나 녹음하지 않아요.</p>`;if(id==='talk')inner=`<div class="talk-preview"><img src="${portrait}" width="180" height="180" alt="미나 선생님"><p>안녕! 나는 미나야.<br>오늘은 이름과 나이를 이야기해 보자.</p></div><button class="primary" data-talk>수업 안내 보기</button><p class="feedback" role="status">회화 화면 미리보기예요. 실제 AI 대화는 연결되지 않았어요.</p>`;open(`${heading(s.title)}<p>${s.name} · ${s.level}단계</p>${inner}`)}
let wordIndex=0;const words=[['apple','사과'],['cat','고양이'],['sun','해']];
function reviewWord(){const w=words[wordIndex];open(`${heading('단어를 다시 만나요')}<p>복습 미리보기 · ${wordIndex+1} / ${words.length}</p><div class="word-card"><strong>${w[0]}</strong><p id="meaning" hidden>${w[1]}</p></div><button class="primary" data-flip>뜻 보기</button><button data-next hidden>다음 단어 →</button><p class="demo-help">14개 중 3개 단어를 체험해요. 학습 기록은 저장하지 않아요.</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.matches('.close'))dialog.close();if(b.dataset.subject)lesson(b.dataset.subject);if(b.dataset.start)start(b.dataset.start);if(b.hasAttribute('data-review')){wordIndex=0;reviewWord()}if(b.hasAttribute('data-parent'))open(`${heading('부모님 화면 안내')}<p>실제 앱에서는 PIN을 확인한 뒤 열려요.</p><div class="parent-info"><p>영역마다 시작 단계를 따로 정해요.</p><p>오늘의 학습과 아이가 한 말을 살펴봐요.</p><p>목업에는 실제 아이 정보가 없어요.</p></div>`);if(b.dataset.answer)document.querySelector('.feedback').textContent=b.dataset.answer==='correct'?'맞아요! 고양이는 햇빛을 좋아해요.':'이야기를 한 번 더 읽어 봐요.';if(b.dataset.word){const box=document.querySelector('.sentence');if(!box.dataset.words)box.dataset.words='';box.dataset.words+=(box.dataset.words?' ':'')+b.dataset.word;box.textContent=box.dataset.words;b.disabled=true;if(box.dataset.words.split(' ').length===3)document.querySelector('.feedback').textContent=box.dataset.words==='I like apples'?'잘했어요! I like apples.':'순서를 한 번 더 생각해 봐요.'}if(b.hasAttribute('data-reset'))start('write');if(b.hasAttribute('data-flip')){document.querySelector('#meaning').hidden=false;b.hidden=true;document.querySelector('[data-next]').hidden=false}if(b.hasAttribute('data-next')){wordIndex++;if(wordIndex<words.length)reviewWord();else open(`${heading('세 단어를 다시 만났어요')}<p>apple · cat · sun</p><p>미리보기를 끝냈어요. 실제 복습 기록에는 반영되지 않아요.</p><button class="primary close">홈으로 돌아가기</button>`)}if(b.hasAttribute('data-talk'))document.querySelector('.feedback').textContent='인사 → 오늘 쓸 말 → 말해 보기 → 대화 → 정리 순서로 함께해요.';if(b.hasAttribute('data-speech')){const f=document.querySelector('.feedback');if(!('speechSynthesis' in window)){f.textContent='이 브라우저에서는 문장 듣기를 지원하지 않아요.';return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance('Hello, my name is Momo.');u.lang='en-US';u.rate=.8;u.onstart=()=>f.textContent='문장을 듣고 있어요.';u.onend=()=>f.textContent='이제 내 목소리로 말해 봐요. 녹음하지 않아요.';u.onerror=()=>f.textContent='소리를 재생하지 못했어요. 기기의 음성 설정을 확인해 주세요.';speechSynthesis.speak(u)}});
dialog.addEventListener('close',()=>{if('speechSynthesis' in window)speechSynthesis.cancel();trigger?.focus()});
